content.text:
{
  "primary_meaning": "Divine protection, shelter, and refuge (as a bird covers its young)",
  "primary_basis": [
    "Psalm 91:4",
    "Ruth 2:12",
    "Deuteronomy 32:11",
    "Exodus 19:4",
    "Matthew 23:37 / Luke 13:34"
  ],
  "alternatives": [
    {
      "meaning": "Strength, renewal, and soaring empowerment",
      "basis": [
        "Isaiah 40:31",
        "Psalm 103:5"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Swiftness, mobility, or theophanic presence (e.g., 'wings of the wind' or cherubim)",
      "basis": [
        "Psalm 18:10",
        "2 Samuel 22:11",
        "Ezekiel 1 and 10 (cherubim)"
      ],
      "prominence": "common"
    },
    {
      "meaning": "Healing and restorative power",
      "basis": [
        "Malachi 4:2"
      ],
      "prominence": "minority"
    },
    {
      "meaning": "Covenantal covering or marital/protective claim (via garment edge/skirt sense of kanaph)",
      "basis": [
        "Ruth 3:9",
        "Ezekiel 16:8"
      ],
      "prominence": "minority"
    }
  ],
  "has_settled_consensus": true,
  "confidence": "high",
  "notes": "In Christian biblical interpretation the protective-refuge sense of wings (kanaph) is the dominant and most frequently taught symbolism, grounded in both Old Testament imagery of God as an eagle/hen and New Testament application by Jesus. Other senses appear regularly but are secondary or context-specific; the Hebrew range of kanaph (wing/edge/corner) is widely noted yet does not displace the protective reading as primary."
}
